<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>二次函数的值域</title>
<style>
  :root{
    --ink:#1e293b;
    --muted:#64748b;
    --line:#e2e8f0;
    --blue:#2563eb;
    --teal:#0f766e;
    --orange:#ea580c;
    --red:#dc2626;
    --bg:#f5f7fb;
    --card:rgba(255,255,255,.95);
  }
  *{box-sizing:border-box;}
  html,body{margin:0;min-height:100%;}
  body{
    font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",Arial,sans-serif;
    background:
      radial-gradient(circle at 12% 0%, rgba(219,234,254,.9) 0, rgba(219,234,254,0) 34%),
      radial-gradient(circle at 90% 12%, rgba(204,251,241,.65) 0, rgba(204,251,241,0) 30%),
      var(--bg);
    color:var(--ink);
    -webkit-font-smoothing:antialiased;
  }
  .page{max-width:1320px;margin:0 auto;padding:24px 20px 12px;}
  .hero{max-width:1280px;margin:0 auto 14px;padding:4px 4px 0;}
  .eyebrow{
    font-size:12px;letter-spacing:.14em;text-transform:uppercase;
    color:var(--teal);font-weight:800;
  }
  h1{
    font-size:clamp(25px,3.2vw,42px);
    line-height:1.12;letter-spacing:-.03em;margin:8px 0 12px;
  }
  h1 span{color:var(--blue);}
  .problem{
    display:flex;gap:10px;align-items:center;flex-wrap:wrap;
    color:#334155;font-size:16px;
  }
  .problem-label{
    display:inline-flex;align-items:center;height:25px;padding:0 9px;
    background:#e2e8f0;color:#475569;border-radius:7px;
    font-size:12px;font-weight:800;letter-spacing:.08em;
  }
  .problem-eq{
    font-size:clamp(16px,1.8vw,20px);
    font-weight:700;letter-spacing:.01em;
  }
  .workspace{
    max-width:1280px;margin:0 auto;
    display:grid;
    grid-template-columns:minmax(0,1.55fr) minmax(335px,.85fr);
    gap:18px;align-items:start;
  }
  .card{
    background:var(--card);
    border:1px solid rgba(148,163,184,.28);
    border-radius:20px;
    box-shadow:0 12px 30px rgba(15,23,42,.055);
  }
  .stage{padding:12px 12px 14px;min-width:0;}
  .stage-top{
    display:flex;align-items:center;justify-content:space-between;gap:12px;
    padding:6px 6px 9px;min-height:34px;
  }
  .badge{
    display:inline-flex;align-items:center;white-space:nowrap;
    font-size:13px;font-weight:800;color:var(--teal);
    background:#e6fffa;border:1px solid #b2f5ea;
    padding:6px 10px;border-radius:999px;
  }
  .hint{
    font-size:13px;line-height:1.4;color:var(--muted);
    text-align:right;
  }
  .plot-wrap{
    background:#fbfdff;border-radius:15px;overflow:hidden;
    border:1px solid #edf2f7;
  }
  svg#plot{display:block;width:100%;height:auto;}
  .controls{
    display:flex;align-items:stretch;gap:14px;
    margin-top:12px;padding:0 4px;flex-wrap:wrap;
  }
  .slider-group{flex:1 1 360px;min-width:240px;}
  .slider-group label{
    display:block;font-size:13px;font-weight:800;color:#334155;margin-bottom:7px;
  }
  input[type="range"]{
    appearance:none;-webkit-appearance:none;
    width:100%;height:28px;background:transparent;cursor:pointer;
  }
  input[type="range"]::-webkit-slider-runnable-track{
    height:8px;border-radius:999px;
    background:linear-gradient(90deg,#bfdbfe,#93c5fd);
  }
  input[type="range"]::-webkit-slider-thumb{
    -webkit-appearance:none;appearance:none;
    width:20px;height:20px;margin-top:-6px;border-radius:50%;
    background:var(--blue);border:3px solid #fff;
    box-shadow:0 2px 7px rgba(37,99,235,.35);
  }
  input[type="range"]::-moz-range-track{
    height:8px;border-radius:999px;
    background:linear-gradient(90deg,#bfdbfe,#93c5fd);
  }
  input[type="range"]::-moz-range-thumb{
    width:16px;height:16px;border-radius:50%;
    background:var(--blue);border:3px solid #fff;
    box-shadow:0 2px 7px rgba(37,99,235,.35);
  }
  .slider-readout{
    display:flex;justify-content:space-between;gap:12px;
    font-size:12px;color:var(--muted);margin-top:2px;
  }
  .slider-readout b{color:var(--blue);font-variant-numeric:tabular-nums;}
  .button-row{display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap;}
  .btn{
    appearance:none;border:1px solid #cbd5e1;background:#fff;color:#334155;
    border-radius:10px;padding:9px 13px;font:inherit;font-size:13px;font-weight:800;
    cursor:pointer;transition:transform .14s, box-shadow .14s, background .14s, border-color .14s;
  }
  .btn:hover{background:#f8fafc;box-shadow:0 4px 10px rgba(15,23,42,.06);}
  .btn:active{transform:translateY(1px);}
  .btn:disabled{opacity:.42;cursor:not-allowed;box-shadow:none;transform:none;}
  .btn.primary{
    color:#fff;background:var(--teal);border-color:transparent;
    box-shadow:0 5px 12px rgba(15,118,110,.22);
  }
  .btn.primary:hover{background:#0d6b63;}
  .btn.ghost{background:transparent;}
  .btn.small{padding:8px 11px;font-size:13px;}
  .side{padding:14px;position:sticky;top:16px;}
  .step-nav{
    display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:10px;
  }
  .step-btn{
    appearance:none;display:flex;align-items:center;justify-content:center;gap:5px;
    min-width:0;padding:7px 4px;
    border:1px solid #e2e8f0;border-radius:11px;
    background:#f8fafc;color:#64748b;font:inherit;font-size:12px;font-weight:800;
    cursor:pointer;transition:background .16s,border-color .16s,color .16s,box-shadow .16s;
  }
  .step-btn span{
    display:inline-grid;place-items:center;width:20px;height:20px;border-radius:50%;
    background:#e2e8f0;color:#475569;font-size:11px;font-weight:900;
  }
  .step-btn:hover{background:#f1f5f9;}
  .step-btn.active{
    color:var(--teal);background:#ecfeff;border-color:#5eead4;
    box-shadow:inset 0 0 0 1px #5eead4;
  }
  .step-btn.active span{background:var(--teal);color:#fff;}
  .state-card h2{
    font-size:19px;line-height:1.3;letter-spacing:-.01em;margin:10px 0 6px;
  }
  .state-card p{
    font-size:13.5px;line-height:1.65;color:#475569;margin:0 0 11px;
  }
  .formula-card{
    background:#f8fafc;border:1px solid #e2e8f0;border-radius:14px;
    padding:10px 12px;margin:10px 0;
  }
  .formula-main{
    font-size:18px;font-weight:800;line-height:1.75;color:#1e293b;
    font-variant-numeric:tabular-nums;
  }
  .formula-main.accent{color:var(--teal);}
  .is-hidden{display:none !important;}
  .calc-card{
    background:#fff;border:1px solid #e2e8f0;border-radius:14px;
    padding:5px 12px;margin:10px 0;
  }
  .calc-row{
    display:flex;justify-content:space-between;gap:14px;
    align-items:baseline;font-size:13px;color:#475569;
    padding:8px 0;border-bottom:1px dashed #e2e8f0;
  }
  .calc-row:last-child{border-bottom:none;}
  .calc-row b{color:#0f172a;font-variant-numeric:tabular-nums;white-space:nowrap;}
  .calc-row.strong b{color:var(--blue);}
  .answer-box{
    margin-top:12px;padding:11px 13px;
    border:1px solid #e2e8f0;border-radius:14px;
    background:#f8fafc;
    transition:background .2s,border-color .2s;
  }
  .answer-box.locked .answer-main{color:#94a3b8;}
  .answer-box.revealed{background:#ecfdf5;border-color:#a7f3d0;}
  .answer-box.revealed .answer-main{color:#065f46;}
  .answer-label{
    font-size:11px;font-weight:900;letter-spacing:.12em;color:#64748b;
  }
  .answer-box.revealed .answer-label{color:#0f766e;}
  .answer-main{
    font-size:clamp(23px,3vw,31px);font-weight:900;line-height:1.25;
    margin:3px 0;letter-spacing:-.02em;
  }
  .answer-note{
    font-size:12.5px;line-height:1.55;color:#64748b;
  }
  .answer-box.revealed .answer-note{color:#276749;}
  .panel-actions{display:flex;gap:8px;margin-top:12px;}
  .panel-actions .btn{flex:1;}
  .foot{
    max-width:1280px;margin:4px auto 0;padding:8px 4px 18px;
    color:#94a3b8;font-size:12px;line-height:1.5;
  }

  /* SVG */
  svg text{font-family:inherit;}
  .grid-line{stroke:#e8eef7;stroke-width:1;}
  .axis{stroke:#94a3b8;stroke-width:1.5;fill:none;}
  .tick{stroke:#cbd5e1;stroke-width:1;}
  .tick-label{font-size:12px;fill:#94a3b8;font-variant-numeric:tabular-nums;}
  .axis-label{font-size:14px;font-weight:800;fill:#64748b;}
  .curve{
    fill:none;stroke:var(--blue);stroke-width:3.4;
    stroke-linecap:round;stroke-linejoin:round;
    filter:drop-shadow(0 2px 2px rgba(37,99,235,.13));
  }
  .guide{stroke-width:1.5;stroke-linecap:round;}
  .projection{
    stroke:#94a3b8;stroke-width:1.15;stroke-dasharray:4 5;opacity:.78;
  }
  .vertex-dot{fill:var(--teal);stroke:#fff;stroke-width:2.5;}
  .vertex-label{
    font-size:13px;font-weight:800;fill:var(--teal);
    paint-order:stroke;stroke:#fff;stroke-width:4px;stroke-linejoin:round;
  }
  .tri-line{stroke-width:2.1;stroke-linecap:round;}
  .tri-label{
    font-size:12px;font-weight:800;
    paint-order:stroke;stroke:#fff;stroke-width:4px;stroke-linejoin:round;
  }
  .point{fill:var(--blue);stroke:#fff;stroke-width:3;}
  .point-label{
    font-size:15px;font-weight:900;fill:#1d4ed8;
    paint-order:stroke;stroke:#fff;stroke-width:4px;stroke-linejoin:round;
  }
  .range-line{stroke:var(--teal);stroke-width:2.5;stroke-linecap:round;}
  .range-label{
    font-size:13px;font-weight:900;fill:var(--teal);
    paint-order:stroke;stroke:#fff;stroke-width:4px;stroke-linejoin:round;
  }
  .final-label{
    font-size:14px;font-weight:900;fill:var(--teal);
    paint-order:stroke;stroke:#fff;stroke-width:4px;stroke-linejoin:round;
  }
  .pulse-ring{
    transform-box:fill-box;transform-origin:center;
    animation:pulse 1.8s ease-out infinite;
  }
  @keyframes pulse{
    0%{opacity:.78;transform:scale(.72);}
    72%{opacity:0;transform:scale(2.2);}
    100%{opacity:0;transform:scale(2.2);}
  }
  .note-label{font-size:11px;fill:#94a3b8;}

  @media (max-width:1050px){
    .workspace{grid-template-columns:1fr;}
    .side{position:static;}
  }
  @media (max-width:680px){
    .page{padding:16px 12px 10px;}
    .stage{padding:9px 9px 12px;}
    .stage-top{align-items:flex-start;flex-direction:column;gap:7px;}
    .hint{text-align:left;}
    .controls{gap:10px;}
    .button-row{width:100%;}
    .button-row .btn{flex:1;}
    .side{padding:12px;}
    .step-btn{font-size:11px;gap:3px;padding:7px 2px;}
    .step-btn span{width:18px;height:18px;}
    .formula-main{font-size:16px;}
  }
</style>
</head>
<body>
<div class="page">
  <header class="hero">
    <div class="eyebrow">二次函数 · 值域</div>
    <h1>把每一个函数值 <span>y</span> 找出来</h1>
    <div class="problem">
      <span class="problem-label">题目</span>
      <span class="problem-eq">函数 y = −x<sup>2</sup> + 2x − 14 的值域是 ______</span>
    </div>
  </header>

  <main class="workspace">
    <section class="stage card" aria-label="函数图像与操作区">
      <div class="stage-top">
        <div id="stateBadge" class="badge">第 1 步 / 4 · 观察</div>
        <div id="stateHint" class="hint">拖动滑块或按“播放”，观察点 P 的纵坐标 y。</div>
      </div>

      <div class="plot-wrap">
        <svg id="plot" viewBox="0 0 760 560" role="img" aria-label="函数 y 等于负 x 平方加 2x 减 14 的图像与当前点 P">
          <defs>
            <marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
              <path d="M0,0 L10,5 L0,10 z" fill="#64748b"></path>
            </marker>
            <marker id="arrowTeal" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
              <path d="M0,0 L10,5 L0,10 z" fill="#0f766e"></path>
            </marker>
            <clipPath id="plotClip">
              <rect x="64" y="44" width="640" height="448"></rect>
            </clipPath>
          </defs>

          <rect x="0" y="0" width="760" height="560" fill="#fbfdff"></rect>

          <rect id="shadeRect" x="64" y="244" width="640" height="248" fill="#14b8a6" opacity="0" clip-path="url(#plotClip)"></rect>

          <g id="gridLayer"></g>
          <g id="axesLayer"></g>

          <line id="baseline" x1="64" y1="244" x2="704" y2="244" stroke="#0f766e" stroke-width="1.5" stroke-dasharray="7 7" opacity="0"></line>
          <line id="maxLine" x1="64" y1="244" x2="704" y2="244" stroke="#0f766e" stroke-width="2" stroke-dasharray="9 6" opacity="0"></line>

          <path id="curve" d="" class="curve" clip-path="url(#plotClip)"></path>

          <g id="projectionLayer" style="display:none">
            <line id="projX" class="projection"></line>
            <line id="projY" class="projection"></line>
          </g>

          <g id="vertexLayer" style="display:none">
            <line id="symLine" class="guide" stroke="#0f766e" stroke-dasharray="5 6" opacity="0.58"></line>
            <text id="symLabel" class="vertex-label" text-anchor="start">x = 1</text>
            <circle id="vertexDot" class="vertex-dot" r="6"></circle>
            <text id="vertexLabel" class="vertex-label">V(1, −13)</text>
          </g>

          <g id="triangleLayer" style="display:none">
            <line id="dropLine" class="tri-line" stroke="#dc2626"></line>
            <line id="dLine" class="tri-line" stroke="#ea580c"></line>
            <text id="dropLabel" class="tri-label" fill="#dc2626">(x−1)²</text>
            <text id="dLabel" class="tri-label" fill="#ea580c">|x−1|</text>
          </g>

          <g id="rangeLayer" style="display:none">
            <line id="rangeLine" class="range-line" marker-end="url(#arrowTeal)"></line>
            <line id="rangeCap" class="range-line"></line>
            <text id="rangeLabel" class="range-label" text-anchor="start">y ≤ −13</text>
          </g>

          <g id="pointLayer">
            <circle id="pointP" class="point" r="7"></circle>
            <text id="pLabel" class="point-label">P</text>
          </g>

          <g id="finalLayer" style="display:none">
            <circle id="finalPulse" class="pulse-ring" r="9" fill="none" stroke="#0f766e" stroke-width="2"></circle>
            <text id="finalText" class="final-label" text-anchor="start">最大值 −13</text>
          </g>

          <text x="696" y="540" text-anchor="end" class="note-label">纵向压缩显示；横轴刻度间隔 2，纵轴刻度间隔 5</text>
        </svg>
      </div>

      <div class="controls">
        <div class="slider-group">
          <label for="xSlider">点 P 的横坐标 x</label>
          <input id="xSlider" type="range" min="-3.2" max="5.2" step="0.05" value="3.00">
          <div class="slider-readout">
            <span>x = <b id="sliderX">3</b></span>
            <span>演示范围 [−3.2, 5.2]</span>
          </div>
        </div>
        <div class="button-row">
          <button id="playBtn" class="btn" type="button">播放</button>
          <button id="vertexBtn" class="btn" type="button">到顶点</button>
          <button id="resetBtn" class="btn ghost" type="button">复位</button>
        </div>
      </div>
    </section>

    <aside class="side card" aria-label="步骤与数值面板">
      <nav class="step-nav" aria-label="解题步骤">
        <button class="step-btn active" data-step="0" type="button" aria-pressed="true"><span>1</span>观察</button>
        <button class="step-btn" data-step="1" type="button" aria-pressed="false"><span>2</span>配方</button>
        <button class="step-btn" data-step="2" type="button" aria-pressed="false"><span>3</span>非负</button>
        <button class="step-btn" data-step="3" type="button" aria-pressed="false"><span>4</span>取等</button>
      </nav>

      <div class="state-card">
        <h2 id="stateTitle">先看函数值怎样变化</h2>
        <p id="stateText">点 P 的纵坐标就是函数值 y。让 P 沿抛物线移动，注意 y 的最高位置。</p>
      </div>

      <div class="formula-card">
        <div class="formula-main">y = −x<sup>2</sup> + 2x − 14</div>
        <div id="vertexFormula" class="formula-main accent is-hidden">y = −(x − 1)<sup>2</sup> − 13</div>
      </div>

      <div class="calc-card">
        <div class="calc-row">
          <span>当前点 P</span>
          <b id="coordLive">(3, −17)</b>
        </div>
        <div class="calc-row is-hidden" id="dRow">
          <span>|x − 1|</span>
          <b id="dLive">2</b>
        </div>
        <div class="calc-row is-hidden" id="sqRow">
          <span>(x − 1)<sup>2</sup></span>
          <b id="sqLive">4</b>
        </div>
        <div class="calc-row strong">
          <span id="yFormulaLabel">函数值 y</span>
          <b id="yLive">−17</b>
        </div>
      </div>

      <div id="answerBox" class="answer-box locked">
        <div class="answer-label">值域</div>
        <div class="answer-main" id="answerMain">？</div>
        <div class="answer-note" id="answerNote">先拖动点，观察 y 的最高位置。</div>
      </div>

      <div class="panel-actions">
        <button id="prevBtn" class="btn small" type="button" disabled>上一步</button>
        <button id="nextBtn" class="btn primary small" type="button">下一步</button>
      </div>
    </aside>
  </main>

  <footer class="foot">
    x 的实际定义域为全体实数；滑块只展示一段便于观察的有限区间。图像按同一函数式计算，纵向经过压缩显示。
  </footer>
</div>

<script>
(function(){
  'use strict';

  const $ = (id) => document.getElementById(id);

  const view = { l:64, r:704, t:44, b:492 };
  const xMin = -4, xMax = 6;
  const yMin = -34, yMax = 4;
  const plotW = view.r - view.l;
  const plotH = view.b - view.t;

  const X = (x) => view.l + ((x - xMin) / (xMax - xMin)) * plotW;
  const Y = (y) => view.t + ((yMax - y) / (yMax - yMin)) * plotH;

  // y = -x^2 + 2x - 14 = -13 - (x-1)^2
  const f = (x) => -13 - Math.pow(x - 1, 2);

  const state = {
    step: 0,
    x: 3.0,
    playing: false
  };

  let direction = 1;
  let lastTs = null;
  let rafId = null;

  const STEPS = [
    {
      label: '观察',
      hint: '拖动滑块或按“播放”，观察点 P 的纵坐标 y。',
      title: '先看函数值怎样变化',
      text: '点 P 的纵坐标就是函数值 y。让 P 沿抛物线移动，注意 y 的最高位置。'
    },
    {
      label: '配方',
      hint: '橙色段是 |x−1|，红色段是 (x−1)²。',
      title: '以 x = 1 为中心配方',
      text: '把函数写成 y = −(x−1)² − 13。函数值 = 基准 −13 减去平方项。'
    },
    {
      label: '非负',
      hint: '曲线全部位于水平线 y = −13 的下方或线上。',
      title: '平方项压出了上界',
      text: '因为 (x−1)² ≥ 0，所以 −(x−1)² ≤ 0，于是 y ≤ −13。'
    },
    {
      label: '取等',
      hint: 'x = 1 时等号成立，曲线继续向下无限延伸。',
      title: '等号能取到，值域确定',
      text: 'x = 1 时 y = −13；曲线向下无限延伸，所以所有 y ≤ −13 都能取到。'
    }
  ];

  const els = {
    xSlider: $('xSlider'),
    sliderX: $('sliderX'),
    playBtn: $('playBtn'),
    vertexBtn: $('vertexBtn'),
    resetBtn: $('resetBtn'),
    stateBadge: $('stateBadge'),
    stateHint: $('stateHint'),
    stateTitle: $('stateTitle'),
    stateText: $('stateText'),
    vertexFormula: $('vertexFormula'),
    coordLive: $('coordLive'),
    dRow: $('dRow'),
    sqRow: $('sqRow'),
    dLive: $('dLive'),
    sqLive: $('sqLive'),
    yFormulaLabel: $('yFormulaLabel'),
    yLive: $('yLive'),
    answerBox: $('answerBox'),
    answerMain: $('answerMain'),
    answerNote: $('answerNote'),
    prevBtn: $('prevBtn'),
    nextBtn: $('nextBtn'),
    stepBtns: Array.from(document.querySelectorAll('.step-btn'))
  };

  function fmt(v, digits = 2){
    if (Math.abs(v) < 0.005) v = 0;
    let s = Math.abs(v).toFixed(digits);
    if (digits > 0) s = s.replace(/\.?0+$/, '');
    if (s === '' || s === '-0') s = '0';
    return (v < 0 ? '−' : '') + s;
  }

  function derive(){
    const x = state.x;
    const sq = Math.pow(x - 1, 2);
    const y = -13 - sq;
    return { x, y, d: Math.abs(x - 1), sq };
  }

  function buildGrid(){
    const grid = $('gridLayer');
    const axes = $('axesLayer');
    let gh = '';

    for (let x = Math.ceil(xMin); x <= xMax; x += 1){
      const px = X(x);
      gh += `<line x1="${px}" y1="${view.t}" x2="${px}" y2="${view.b}" class="grid-line"></line>`;
    }
    for (let y = -30; y <= 0; y += 5){
      const py = Y(y);
      gh += `<line x1="${view.l}" y1="${py}" x2="${view.r}" y2="${py}" class="grid-line"></line>`;
    }
    grid.innerHTML = gh;

    const gy = Y(0);
    const gx = X(0);
    let ah = `
      <line x1="${view.l}" y1="${gy}" x2="${view.r + 10}" y2="${gy}" class="axis" marker-end="url(#arrow)"></line>
      <line x1="${gx}" y1="${view.b}" x2="${gx}" y2="${view.t - 10}" class="axis" marker-end="url(#arrow)"></line>
      <text x="${view.r + 15}" y="${gy + 5}" class="axis-label">x</text>
      <text x="${gx + 10}" y="${view.t - 1}" class="axis-label">y</text>
    `;

    for (let x = -4; x <= 6; x += 2){
      const px = X(x);
      ah += `<line x1="${px}" y1="${gy - 4}" x2="${px}" y2="${gy + 4}" class="tick"></line>`;
      ah += `<text x="${px}" y="${gy + 20}" text-anchor="middle" class="tick-label">${fmt(x, 0)}</text>`;
    }

    for (let y = -30; y <= 0; y += 5){
      const py = Y(y);
      ah += `<line x1="${gx - 4}" y1="${py}" x2="${gx + 4}" y2="${py}" class="tick"></line>`;
      if (y !== 0){
        ah += `<text x="${gx - 9}" y="${py + 4}" text-anchor="end" class="tick-label">${fmt(y, 0)}</text>`;
      }
    }

    axes.innerHTML = ah;
  }

  function buildCurve(){
    let d = '';
    const samples = 720;
    for (let i = 0; i <= samples; i++){
      const x = xMin + (xMax - xMin) * i / samples;
      const y = f(x);
      d += (i === 0 ? 'M' : 'L') + X(x).toFixed(2) + ' ' + Y(y).toFixed(2) + ' ';
    }
    $('curve').setAttribute('d', d);
  }

  function initGeometry(){
    const y13 = Y(-13);

    const baseline = $('baseline');
    const maxLine = $('maxLine');
    [baseline, maxLine].forEach((line) => {
      line.setAttribute('x1', view.l);
      line.setAttribute('x2', view.r);
      line.setAttribute('y1', y13);
      line.setAttribute('y2', y13);
    });

    const shade = $('shadeRect');
    shade.setAttribute('x', view.l);
    shade.setAttribute('y', y13);
    shade.setAttribute('width', plotW);
    shade.setAttribute('height', Y(yMin) - y13);

    const vx = X(1);
    const vy = Y(-13);

    $('vertexDot').setAttribute('cx', vx);
    $('vertexDot').setAttribute('cy', vy);
    $('finalPulse').setAttribute('cx', vx);
    $('finalPulse').setAttribute('cy', vy);

    $('vertexLabel').setAttribute('x', vx + 12);
    $('vertexLabel').setAttribute('y', vy - 10);

    $('symLine').setAttribute('x1', vx);
    $('symLine').setAttribute('x2', vx);
    $('symLine').setAttribute('y1', view.t);
    $('symLine').setAttribute('y2', view.b);

    $('symLabel').setAttribute('x', vx + 8);
    $('symLabel').setAttribute('y', view.t + 18);

    const rx = X(5.66);
    const rTop = Y(-13);
    const rBot = Y(-31.5);

    const rangeLine = $('rangeLine');
    rangeLine.setAttribute('x1', rx);
    rangeLine.setAttribute('x2', rx);
    rangeLine.setAttribute('y1', rTop);
    rangeLine.setAttribute('y2', rBot);

    const rangeCap = $('rangeCap');
    rangeCap.setAttribute('x1', rx - 8);
    rangeCap.setAttribute('x2', rx + 8);
    rangeCap.setAttribute('y1', rTop);
    rangeCap.setAttribute('y2', rTop);

    $('rangeLabel').setAttribute('x', rx + 10);
    $('rangeLabel').setAttribute('y', rTop - 8);

    $('finalText').setAttribute('x', vx + 14);
    $('finalText').setAttribute('y', vy - 46);
  }

  function updatePlot(p){
    const px = X(p.x);
    const py = Y(p.y);
    const qx = X(1);
    const vy = Y(-13);
    const yAxisX = X(0);
    const xAxisY = Y(0);

    $('pointP').setAttribute('cx', px);
    $('pointP').setAttribute('cy', py);

    $('pLabel').setAttribute('x', px + 14);
    $('pLabel').setAttribute('y', py - 10);
    $('pLabel').textContent = 'P';
    $('pLabel').style.opacity = p.d < 0.04 ? '0' : '1';

    $('projX').setAttribute('x1', px);
    $('projX').setAttribute('y1', py);
    $('projX').setAttribute('x2', px);
    $('projX').setAttribute('y2', xAxisY);

    $('projY').setAttribute('x1', px);
    $('projY').setAttribute('y1', py);
    $('projY').setAttribute('x2', yAxisX);
    $('projY').setAttribute('y2', py);

    $('dropLine').setAttribute('x1', qx);
    $('dropLine').setAttribute('y1', vy);
    $('dropLine').setAttribute('x2', qx);
    $('dropLine').setAttribute('y2', py);

    $('dLine').setAttribute('x1', qx);
    $('dLine').setAttribute('y1', py);
    $('dLine').setAttribute('x2', px);
    $('dLine').setAttribute('y2', py);

    const bigEnough = p.d > 0.06;
    $('dropLine').style.opacity = bigEnough ? '1' : '0';
    $('dLine').style.opacity = bigEnough ? '1' : '0';

    $('dropLabel').setAttribute('x', qx - 8);
    $('dropLabel').setAttribute('y', (vy + py) / 2 + 4);
    $('dropLabel').setAttribute('text-anchor', 'end');
    $('dropLabel').style.opacity = bigEnough ? '1' : '0';

    $('dLabel').setAttribute('x', (qx + px) / 2);
    $('dLabel').setAttribute('y', py + 18);
    $('dLabel').setAttribute('text-anchor', 'middle');
    $('dLabel').style.opacity = bigEnough ? '1' : '0';

    $('projectionLayer').style.display = state.step === 0 ? '' : 'none';
    $('vertexLayer').style.display = state.step >= 1 ? '' : 'none';
    $('triangleLayer').style.display = state.step >= 1 ? '' : 'none';
    $('rangeLayer').style.display = state.step >= 2 ? '' : 'none';
    $('finalLayer').style.display = state.step >= 3 ? '' : 'none';

    $('baseline').style.display = state.step >= 1 ? '' : 'none';
    $('maxLine').style.display = state.step >= 2 ? '' : 'none';
    $('shadeRect').style.opacity = state.step >= 2 ? '0.075' : '0';
  }

  function updatePanel(p){
    const step = state.step;
    const info = STEPS[step];

    els.stateBadge.textContent = `第 ${step + 1} 步 / 4 · ${info.label}`;
    els.stateHint.textContent = info.hint;
    els.stateTitle.textContent = info.title;
    els.stateText.textContent = info.text;

    els.xSlider.value = p.x.toFixed(2);
    els.sliderX.textContent = fmt(p.x);
    els.coordLive.textContent = `(${fmt(p.x)}, ${fmt(p.y)})`;
    els.dLive.textContent = fmt(p.d);
    els.sqLive.textContent = fmt(p.sq);
    els.yLive.textContent = fmt(p.y);

    els.vertexFormula.classList.toggle('is-hidden', step < 1);
    els.dRow.classList.toggle('is-hidden', step < 1);
    els.sqRow.classList.toggle('is-hidden', step < 1);
    els.yFormulaLabel.innerHTML = step < 1
      ? '函数值 y'
      : 'y = −13 − (x−1)<sup>2</sup>';

    els.answerBox.classList.toggle('locked', step < 3);
    els.answerBox.classList.toggle('revealed', step >= 3);

    if (step >= 3){
      els.answerMain.textContent = '(−∞, −13]';
      els.answerNote.textContent = 'x = 1 时取到最大值 −13；曲线向下无限延伸，所有 y ≤ −13 都能取到。';
    } else {
      els.answerMain.textContent = '？';
      if (step === 0){
        els.answerNote.textContent = '先拖动点，观察 y 的最高位置。';
      } else if (step === 1){
        els.answerNote.textContent = '配方后，平方项是唯一的“下降量”。';
      } else {
        els.answerNote.textContent = '已得 y ≤ −13，还要确认等号能否取到。';
      }
    }

    els.prevBtn.disabled = step === 0;
    els.nextBtn.disabled = step === 3;

    els.stepBtns.forEach((btn, i) => {
      const active = i === step;
      btn.classList.toggle('active', active);
      btn.setAttribute('aria-pressed', active ? 'true' : 'false');
    });

    els.playBtn.textContent = state.playing ? '暂停' : '播放';
  }

  function render(){
    const p = derive();
    updatePanel(p);
    updatePlot(p);
  }

  function stopPlay(){
    state.playing = false;
    lastTs = null;
    direction = 1;
    if (rafId !== null){
      cancelAnimationFrame(rafId);
      rafId = null;
    }
  }

  function animate(ts){
    if (!state.playing){
      rafId = null;
      return;
    }

    if (lastTs === null) lastTs = ts;
    const dt = Math.min(0.05, (ts - lastTs) / 1000);
    lastTs = ts;

    state.x += direction * 1.55 * dt;
    if (state.x >= 5.2){
      state.x = 5.2;
      direction = -1;
    }
    if (state.x <= -3.2){
      state.x = -3.2;
      direction = 1;
    }

    render();
    rafId = requestAnimationFrame(animate);
  }

  function setStep(n){
    stopPlay();
    state.step = Math.max(0, Math.min(3, n));
    if (state.step === 3){
      state.x = 1;
    }
    render();
  }

  els.xSlider.addEventListener('input', (e) => {
    stopPlay();
    state.x = parseFloat(e.target.value);
    render();
  });

  els.playBtn.addEventListener('click', () => {
    if (state.playing){
      stopPlay();
      render();
      return;
    }
    state.playing = true;
    lastTs = null;
    direction = 1;
    render();
    rafId = requestAnimationFrame(animate);
  });

  els.vertexBtn.addEventListener('click', () => {
    stopPlay();
    state.x = 1;
    if (state.step < 1) state.step = 1;
    render();
  });

  els.resetBtn.addEventListener('click', () => {
    stopPlay();
    state.step = 0;
    state.x = 3;
    direction = 1;
    render();
  });

  els.prevBtn.addEventListener('click', () => setStep(state.step - 1));
  els.nextBtn.addEventListener('click', () => setStep(state.step + 1));

  els.stepBtns.forEach((btn) => {
    btn.addEventListener('click', () => {
      setStep(parseInt(btn.dataset.step, 10));
    });
  });

  buildGrid();
  buildCurve();
  initGeometry();
  render();
})();
</script>
</body>
</html>
